/**
 * LogPurgeJob
 *
 * Nightly purge of FB_Integration_Log__c.
 *
 * Retention rules:
 *   - Level__c = 'ERROR'                          -> kept for 180 days
 *   - any other level (DEBUG, INFO, blank/null)   -> kept for 30 days
 *
 * The scheduled class itself only enqueues a batch job. A log table that has
 * been filling up storage can easily hold more rows than a single transaction
 * may query or delete (50,000 query rows / 10,000 DML rows), so the actual
 * deletion is chunked by Batch Apex.
 *
 * The job runs without sharing on purpose: purging must not depend on the
 * sharing rules or record access of the user who scheduled it.
 */
public without sharing class LogPurgeJob implements Schedulable {

    /** Retention (in days) for logs that are not errors. */
    @TestVisible
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** Retention (in days) for logs with Level__c = 'ERROR'. */
    @TestVisible
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Chunk size used by the deletion batch. */
    @TestVisible
    private static final Integer BATCH_SIZE = 2000;

    /**
     * Schedulable entry point: enqueues the purge batch.
     */
    public void execute(SchedulableContext context) {
        Database.executeBatch(new PurgeBatch(), BATCH_SIZE);
    }

    /**
     * Schedules the purge every day at 02:00 under the name
     * 'Log purge (nightly)' and returns the Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }

    /**
     * Deletes stale FB_Integration_Log__c rows in chunks of BATCH_SIZE.
     */
    public without sharing class PurgeBatch implements Database.Batchable<SObject> {

        public Database.QueryLocator start(Database.BatchableContext context) {
            DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
            DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

            // Level__c is optional. A plain "Level__c != 'ERROR'" does not match
            // null values in SOQL, so blank levels are matched explicitly.
            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != 'ERROR' OR Level__c = null))
                   OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
            ]);
        }

        public void execute(Database.BatchableContext context, List<SObject> scope) {
            // allOrNone = false: a single locked row must not abort the whole purge.
            Database.delete(scope, false);
        }

        public void finish(Database.BatchableContext context) {
            // Nothing to do.
        }
    }
}
